module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum reg [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    reg [1:0] state, next_state;
    reg [1:0] byte_count;  // counts received bytes (1, 2, 3)

    // Next-state logic (combinational)
    always @(*) begin
        case (state)
            IDLE: begin
                if (in[3]) next_state = BYTE1;
                else       next_state = IDLE;
            end
            BYTE1: begin
                if (byte_count == 2) next_state = BYTE2;
                else                 next_state = BYTE1; // stay until 2nd byte arrives
            end
            BYTE2: begin
                if (byte_count == 3) next_state = BYTE3;
                else                 next_state = BYTE2; // stay until 3rd byte arrives
            end
            BYTE3: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // State flip-flops (sequential, positive edge, async reset)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            byte_count <= 1'b0;
            done      <= 1'b0;
            out_bytes <= 24'b0;
        end else begin
            state <= next_state;

            // Update byte count based on state transition
            case (state)
                IDLE: begin
                    if (in[3]) byte_count <= 1'b1; // first byte captured
                    else       byte_count <= 1'b0;
                end
                BYTE1: begin
                    if (byte_count == 1) byte_count <= 2'b10; // move to 2nd byte position
                end
                BYTE2: begin
                    if (byte_count == 2) byte_count <= 3'b100; // move to 3rd byte position
                end
                BYTE3: begin
                    // byte_count stays at 3
                end
            endcase

            // Generate done pulse one cycle after 3rd byte received
            if (state == BYTE3 && next_state == IDLE) begin
                done <= 1'b1;
            end else begin
                done <= 1'b0;
            end

            // Shift in the received bytes
            case (state)
                IDLE: begin
                    // Do not shift; wait for first byte with in[3]=1
                end
                BYTE1: begin
                    // First byte goes to out_bytes[23:16]
                    out_bytes[23:16] <= in;
                end
                BYTE2: begin
                    // Second byte goes to out_bytes[15:8]
                    out_bytes[15:8]  <= in;
                end
                BYTE3: begin
                    // Third byte goes to out_bytes[7:0]
                    out_bytes[7:0]   <= in;
                end
            endcase
        end
    end

endmodule

