module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A   = 3'b000,
        STATE_B   = 3'b001,
        STATE_C   = 3'b010,
        STATE_D   = 3'b011,
        STATE_E   = 3'b100
    } state_t;

    state_t state, next_state;

    // Outputs (combinational logic)
    assign f = (state == STATE_A) ? 1'b0 : 1'b1;
    assign g = (state == STATE_D) ? 1'b1 : 1'b0;

    // State register (positive edge triggered, synchronous active-low reset)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= STATE_A;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        next_state = state; // default: stay in current state

        case (state)
            STATE_A: begin
                // On de-assertion of reset, go to STATE_B and set f=1 for one cycle
                next_state = STATE_B;
            end

            STATE_B: begin
                // Monitor x for pattern 1, 0, 1 over three cycles
                // After one cycle in B, if x==1 go to C, else stay in B
                if (x == 1'b1)
                    next_state = STATE_C;
                // else remain in STATE_B
            end

            STATE_C: begin
                // We have seen x=1 in the first cycle of monitoring.
                // Now wait for x=0 in the next cycle.
                if (x == 1'b0)
                    next_state = STATE_D; // pattern 1,0 seen, go to D
                // else remain in STATE_C (waiting for 0)
            end

            STATE_D: begin
                // We have seen pattern 1,0,1. g should become 1 on the next cycle.
                // Now monitor y: if y becomes 1 within 2 cycles, stay in D (g=1 forever).
                // If 2 cycles pass without y=1, go to STATE_E (g=0 forever).
                if (y == 1'b1)
                    next_state = STATE_D; // y became 1 in time -> stay in D (g=1)
                else
                    next_state = STATE_E; // y not 1 yet -> transition to E (g=0)
            end

            STATE_E: begin
                // Absorbing state: g=0 permanently until reset.
                // Stay in E regardless of inputs.
                next_state = STATE_E;
            end

            default: next_state = STATE_A;
        endcase
    end

endmodule

