module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    wire [2:0] s_synced;
    reg  [2:0] s_prev;
    reg  [1:0] level_state; // 00: above s2, 01: between s2 and s1, 10: between s1 and s0, 11: below s0
    reg        dfr_reg;

    // Synchronize inputs
    always @(posedge clk) begin
        if (reset) begin
            s_prev       <= 3'b000;
            level_state  <= 2'b11; // below s0
            dfr_reg      <= 1'b1;
        end else begin
            s_prev       <= s;
            // Determine level state based on current sensors
            if (s[2]) level_state <= 2'b00; // above s2
            else if (s[1]) level_state <= 2'b01; // between s2 and s1
            else if (s[0]) level_state <= 2'b10; // between s1 and s0
            else        level_state <= 2'b11; // below s0

            // dfr logic: increase flow if previous level was lower than current
            // Previous lower means we transitioned from a higher state index to a lower one (e.g., 10 -> 01 or 01 -> 00 or 11 -> anything lower)
            // Simplified: if current state is 'higher' (numerically smaller index) than previous, open dfr.
            // State order: 00 (top) -> 01 -> 10 -> 11 (bottom).
            // "Lower than current" means previous index > current index.
            if (s_prev > s) begin
                dfr_reg <= 1'b1;
            end else if (s_prev < s) begin
                dfr_reg <= 1'b0;
            end
            // If equal, dfr retains previous value (implicitly kept here by not resetting)
        end
    end

    // Output assignments based on level_state and dfr_reg
    assign fr0 = (level_state == 2'b10) || (level_state == 2'b11); // Between s1-s0 or below s0
    assign fr1 = (level_state == 2'b11); // Below s0
    assign fr2 = (level_state == 2'b11); // Below s0
    assign dfr = dfr_reg;

    // Active-high synchronous reset handling is inside the always block above.

endmodule
